bad = 0; n = 0
for f, want in T:
    n += 1
    try: b.set_input(S, 13, 9, '=' + f); got = b.value(S, 13, 9)
    except BaseException as e: got = ("EXC", str(e)[:80])
    tol = 1e-9
    if isinstance(want, tuple) and len(want) == 2 and isinstance(want[0], (int, float)) and not isinstance(want[0], bool): want, tol = want
    if isinstance(want, tuple): ok = isinstance(got, (tuple, list)) and tuple(got) == want
    elif isinstance(want, bool): ok = got is want
    elif isinstance(want, (int, float)): ok = isinstance(got, (int, float)) and not isinstance(got, bool) and abs(got - want) <= tol * max(1, abs(want))
    else: ok = got == want
    if not ok: bad += 1; print("DIFF  =%s   want %r   got %r" % (f, want, got))
print("formulas2: %d checked, %d differ" % (n, bad))
